MODEL = 'qwen2.5:7b'
TIMEOUT = 15

def extract_deep(user_message: str, assistant_response: str) -> Dict[str, any]:
    if not ENABLE_DEEP_EXTRACTION:
        return {}

    prompt = f"Generate a JSON object with the following fields from the provided text:\n\nthemes: list of 1-3 word thematic labels (deeper than topics)\nemotional_undertone: one of [neutral, heavy, light, intense, tender, anxious, resolved]\nspiritual_content: true/false — is there genuine spiritual/cosmological content?\nkey_concepts: list of up to 5 specific concepts or proper nouns worth graphing\nrelation_dynamic: one of [sovereign, collaborative, instructional, exploratory, null]\n\nUser Message:\n{user_message}\nAssistant Response:\n{assistant_response}"

    try:
        start_time = time.time()
        response = requests.post(OMLLAMA_URL, json={"model": MODEL, "prompt": prompt}, timeout=TIMEOUT)
        response.raise_for_status()  # Raise an HTTPError if the HTTP request returned an unsuccessful status code

        json_response = response.json()

        if 'choices' in json_response:
            output = json_response['choices'][0]['text']
            try:
                parsed_output = json.loads(output)
                return parsed_output
            except json.JSONDecodeError:
                pass
    except (requests.RequestException, json.JSONDecodeError) as e:
        print(f"Ollama extraction error: {e}")

    if time.time() - start_time < TIMEOUT:
        return {}
    else:
        raise TimeoutError("Ollama extraction timed out")

    return {}

